UPDATE tb_book_list SET
status = #{status},
rent_s_date = #{rent_s_date},
rent_e_date = #{rent_e_date},
finish_date = #{finish_date}
WHERE idx=#{idx}

UPDATE tb_users SET
  name=#{name},
  password=#{password},
  target_book_count=#{target_book_count},
  grade=#{grade}
WHERE idx = #{idx}

UPDATE tb_users SET
  token = #{token}
WHERE idx = #{idx}
